dict(id="embedded-redivision-search", name="Hidden redivision search (target inside a run of text)", category="redivision",
 summary="Search the digitized text for any run of consecutive letters whose Morse bits contain a target word's bits. Penn treats such a run as a hidden occurrence of the word.",
 rules="Digitize every text: letters to Morse, numerals to binary, everything else dropped. A run x 'is' a redivision of target y if y's bits lie inside x's bits, starting inside x's first letter and ending inside its last. Partial letters at both ends are allowed. It is 'perfect' if no digits are left over. Penn searched with Microsoft Word find, and converted a digital position to a literal one by dividing by 2.58 (the average Morse length of an English letter). Rarer (longer) targets count for more.",
 examples=[
  X("GGESTS (O'Hare, 'Reflections on trust and confidence', 1994)", "110 110 0 000 1 000 contains KNIFE (101 10 00 0010 0)", "With YWHENA, 136 = 8 x 17 characters apart (GZ4216 2010).", ('in','GGESTS','KNIFE'), ('in','YWHENA','KNIFE')),
  X("[DOW]NTHERETHERE[A] (LA Times letter 1971)", "contains RIVERSIDE (22 bits)", "A 'hapax' in the only letter about Riverside; odds 1/2^22 claimed (Penn 2022).", ('in','NTHERETHEREA','RIVERSIDE')),
  X("ODSTAI (from a word in the Stine letter)", "contains OHARE", "Penn says the shirt-piece wording was chosen for this (SP p.22).", ('in','ODSTAI','OHARE')),
  X("THECO", "1 0000 0 1010 111 = BERTA M (perfect)", "SP p.24.", ('rd','THECO','BERTA M')),
  X("LOOSE ALL (Belli letter, around the struck-out 'complet')", "contains OHARE", "The crossed-out word 'divides OHARE in two' (SP p.25).", ('in','LOOSEALL','OHARE')),
  X("FROM WHENCE (Count Marco letter, 1974)", "ROMWH contains TWO PI (1 011 111 0110 00)", "The only TWO PI in the corpus (Penn 2022).", ('in','ROMWH','TWOPI')),
 ],
 claims="Penn claims these placements are deliberate: rare targets in thematically matching texts.",
 first_seen="1999 (The Second Power; computer searches)",
 citations=["SP:9-10", "SP:22", "SP:24-25", "GZ4216 blog 7 Jun 2010, gp24", "GZ4216 blog 7 Jun 2010, gp26-27", "Penn 2022, 'Radian'", "Penn 2022, 'The Zodiac literature: digital, multidimensional, nonverbal'"],
 demo=D("redivision", "GGESTS|KNIFE", "KNIFE found inside GGESTS"),
 related=["digital-redivision","hapax-rarity","hidden-family-vocabulary","comparative-authorship"]),

